    "authority_fingerprint",get "fingerprint" raw;"request_fingerprint",get "fingerprint" raw;
    "resources",get "resources" expected_profile] in
  require (Json.equal actual.result expected) "Complete authority-only receipt binding changed"
let error ?message ?path code action =
  try ignore (action ()); failwith ("Expected "^code)
  with Diagnostic.Error value ->
    require (value.code=code) ("Expected "^code^", got "^value.code^": "^value.message);
    Option.iter (fun expected -> require (value.message=expected) value.message) message;
    Option.iter (fun expected -> require (value.path=expected) "Wrong authority diagnostic path") path
let reduced key value =
  let defaults = get "workflow" (get "resources" expected_profile) in
  replace "limits" (Json.Object (List.map (fun name -> name,
    if name=key then value else get name defaults)
    ["max_work";"max_monitor_items";"max_request_bytes";"max_report_bytes";"max_report_nodes"])) payload
let with_reduction key value authority =
  let control = reduced key (Json.int value) in
  call ~control (B.create ~limits:(A.limits_of_payload control) ()) authority
let () =
  require (List.length cases=9 && Canonical.fingerprint literals=literal_hash) "Independent authority census changed";
  require (Json.equal A.profile expected_profile) "Complete authority profile differs from independent contract";
  require (A.profiles=["verification_workflow_authority",A.profile] && A.operations=[operation] &&
    A.validation_scopes=["fresh_source_authority_only"]) "Authority capability scope changed";
  List.iter (fun raw ->
    let authority = get "request" raw in
    List.iter (fun executable ->
      let budget = B.create () in
      check raw executable (call ~executable budget authority);
      let usage = B.usage budget in
      require (usage.evaluations=0 && usage.request_bytes=(X.Codec.measure authority).bytes+1 &&
        usage.report_bytes=String.length (X.Codec.encode authority) && usage.report_nodes=(X.Codec.measure authority).nodes)
        "Authority service evaluated a workflow or omitted complete input/publication accounting")
      [Protocol.Core;Protocol.Verify]) cases;
  let raw = case "candidate_pass" in
  let authority = get "request" raw in
  let original = call (B.create ()) authority in
  let candidate = get "candidate" authority in
  let reordered = replace "component_locks" (Json.Array (List.rev (Json.array (get "component_locks" candidate)))) candidate in
  let reordered_authority = replace "candidate" reordered authority in
  let normalized = call (B.create ()) reordered_authority in
  require (normalized.artifact=original.artifact &&
    get "authority_fingerprint" normalized.result=Json.String (X.Codec.fingerprint reordered_authority) &&
    get "request_fingerprint" normalized.result=get "request_fingerprint" original.result &&
    get "authority_fingerprint" normalized.result<>get "request_fingerprint" normalized.result)
    "Raw authority was silently normalized before its identity was retained";
  let float_horizon = replace "until" (Json.Float 9.) authority in
  let numeric = call (B.create ()) float_horizon in
  require (numeric.artifact=X.Codec.encode float_horizon && numeric.artifact<>original.artifact)
    "Numeric representation was erased from complete request publication";
  let realization = get "realization" authority in
  let behavior = get "behavior" realization in
  let forged = replace "realization" (replace "behavior" (replace "name" (Json.String "forged") behavior) realization) authority in
  error ~message:"Source semantic fingerprint and program identity match." ~path:None "lowering_source_identity"
    (fun () -> call (B.create ()) forged);
  (* Both a valid and an invalid candidate context pass through fresh source
     authority decoding; a supplied result or outcome cannot bypass this step. *)
  error ~message:"Invalid fields in SyntheticVerificationRequest." ~path:(Some "authority") "verification_workflow"
    (fun () -> call (B.create ()) (replace "outcome" (Json.String "pass") authority));
  let budget = B.create () in
  ignore (call budget authority);
  let charged = (B.usage budget).work_charged in
  let parent = W.create ~profile:"authority-service-test" ~error_code:"authority_parent_limit" ~maximum:charged () in
  check raw Protocol.Core (call (B.create ~parent ()) authority);
  require (W.remaining parent=0) "Authority import, source lowering, hashing or publication escaped the parent";
  let parent = W.create ~profile:"authority-service-test" ~error_code:"authority_parent_limit" ~maximum:(charged-1) () in
  error "authority_parent_limit" (fun () -> call (B.create ~parent ()) authority);
  let request_size = (X.Codec.measure authority).bytes in
  error "workflow_input_limit" (fun () -> with_reduction "max_request_bytes" request_size authority);
  ignore (with_reduction "max_request_bytes" (request_size+1) authority);
  error "verification_exploration_limit" (fun () -> with_reduction "max_report_bytes" (request_size-1) authority);
  error "verification_exploration_limit" (fun () -> with_reduction "max_report_nodes" 1 authority);
  error "workflow_retention_limit" (fun () -> with_reduction "max_monitor_items" 1 authority);
  error "workflow_work_limit" (fun () -> with_reduction "max_work" 1 authority);
  error "workflow_authority_operation" (fun () -> call ~selected_operation:"run-verification-workflow" (B.create ()) authority);
  error "workflow_authority_profile" (fun () -> call ~control:(replace "profile" (Json.String "stale") payload) (B.create ()) authority);
  error "invalid_type" (fun () -> A.limits_of_payload (replace "profile" Json.Null payload));
  error "missing_field" (fun () -> A.limits_of_payload (Json.Object ["profile",get "profile" payload]));
  error "unknown_field" (fun () -> A.limits_of_payload (replace "record" Json.Null payload));
  error "workflow_limits" (fun () -> call ~control:(reduced "max_work" (Json.int 1)) (B.create ()) authority);
  List.iter (fun scalar -> error "workflow_limits" (fun () -> A.limits_of_payload (reduced "max_work" scalar)))
    [Json.int 0;Json.int (-1);Json.Float 1.;Json.Bool true;Json.Null;Json.String "1";
     Json.Int Z.(add (Json.integer (get "max_work" (get "workflow" (get "resources" expected_profile)))) one)];
  error "workflow_limits" (fun () -> A.limits_of_payload (replace "limits" (Json.Array []) payload));
  let reductions = Json.Object ["max_work",Json.int 1_000_000_000_000;
    "max_monitor_items",Json.int 7_000_000;"max_request_bytes",Json.int 16_777_216;
    "max_report_bytes",Json.int 1_048_576;"max_report_nodes",Json.int 100_000] in
  let control = replace "limits" reductions payload in
  let budget = B.create ~limits:(A.limits_of_payload control) () in
  let actual = call ~control budget authority in
  require (actual.artifact=original.artifact && (B.usage budget).evaluations=0) "Authority reduction changed semantic content";
  let rec mapped = function
    | Json.Object values -> Json.Object (List.map (fun (key,value) -> key,
        (match List.assoc_opt key (Json.object_fields reductions),value with
         | Some (Json.Int maximum),Json.Int old -> Json.Int (Z.min maximum old)
         | _ -> if key="max_evaluation_work" then Json.int 50_000_000 else mapped value)) values)
    | value -> value in
  require (Json.equal (get "resources" actual.result) (mapped (get "resources" expected_profile)))
    "Authority receipt hides the actual shared reductions"
